-- Health columns used by the supplied legacy export/apply schema.
alter table health_members add column legacy_id text,add column display_name text,add column full_name text,add column gender text,add column dob date,add column blood_type text,add column height_text text,add column weight_text text,add column phone text,add column email text,add column bhyt text,add column bhyt_exp date,add column bhyt_place text,add column bhxh text,add column hospital text,add column doctor text,add column emergency_contact text,add column status_text text,add column status_tone text,add column notes text,add column extra jsonb not null default '{}',add column updated_at timestamptz not null default now();
create table health_measurements(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,legacy_id text,measure_date date,weight_g numeric,height_cm numeric,head_cm numeric,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by_device uuid references devices(id),updated_by_device uuid references devices(id),deleted_at timestamptz);
create table health_visits(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,visit_date date,visit_time text,hospital text,doctor text,symptom text,diagnosis text,treatment text,medicine_note text,cost numeric,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table health_medications(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,name text,dose text,from_date date,to_date date,active boolean not null default true,remind boolean not null default true,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table health_labs(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,lab_date date,title text,place text,result_summary text,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table vaccine_catalog(id uuid primary key,family_id uuid references families(id),name text not null,short_name text,disease text,manufacturer text,is_required boolean not null default false,is_service boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table child_vaccine_plans(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,vaccine_id uuid references vaccine_catalog(id),dose_number int,due_date date,status text not null default 'pending',note text,legacy_id text,schedule_key text,template_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table vaccine_records(id uuid primary key,family_id uuid not null references families(id),member_id uuid not null references health_members(id) on delete cascade,plan_id uuid references child_vaccine_plans(id),vaccine_id uuid references vaccine_catalog(id),vaccine_name text,dose_number int,injection_date date,place text,manufacturer text,lot_number text,reaction text,reaction_level text,note text,legacy_id text,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table pregnancy_records(id uuid primary key,family_id uuid not null references families(id),legacy_id text,exam_date date,week_text text,estimated_weight text,bpd text,hc text,ac text,fl text,afi text,position text,note text,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
do $$declare t text;begin foreach t in array array['health_members','health_measurements','health_visits','health_medications','health_labs','vaccine_catalog','child_vaccine_plans','vaccine_records','pregnancy_records'] loop execute format('alter table %I enable row level security',t);execute format('create trigger updated before update on %I for each row execute function myb_set_updated_at()',t);end loop;end$$;
-- Matching production shell anchors; health/pregnancy sections are removed by 1550.
create or replace function myb_app_shell_v1540(p_sync_id text default 'main') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_members jsonb;v_hb jsonb;v_care jsonb;v_milk jsonb;v_preg jsonb;v_app_members jsonb;v_cont jsonb;begin
 select coalesce(jsonb_agg(member_doc),'[]') into v_members from (select extra member_doc from health_members where family_id=myb_stable_uuid('family:'||p_sync_id)) s;
 v_hb:=jsonb_build_object('members',v_members);
 v_care := '[]'::jsonb; v_milk := '[]'::jsonb;
 select coalesce(jsonb_agg(coalesce(pr.extra,'{}')),'[]') into v_preg from pregnancy_records pr where family_id=myb_stable_uuid('family:'||p_sync_id);
 select coalesce(jsonb_agg(coalesce(am.extra,'{}')),'[]') into v_app_members from health_members am where false;
 select coalesce(jsonb_agg(extra||jsonb_build_object('id',legacy_id,'name',name,'kind',kind,'capacity',capacity_ml,'active',active)),'[]') into v_cont from milk_containers where family_id=myb_stable_uuid('family:'||p_sync_id);
 return jsonb_build_object('ok',true,'family_id',myb_stable_uuid('family:'||p_sync_id),'payload',jsonb_build_object('hb',v_hb,'careEvents',v_care,'milkInventory',v_milk,'pregnancy',v_preg,'milkContainers',v_cont));end$$;
